# -*- coding: utf-8 -*-
"""فصل ۱۱: نقدها و چالش‌ها."""

def ch11(D):
    D.h1("نقدها و چالش‌ها: کجاها مک‌لوهان آسیب‌پذیر است؟", num="۱۱")

    D.h2("۱۱.۱. نقد روش‌شناسی: مبهم، غیرعلمی، غیرقابل‌آزمون")
    D.para("قوی‌ترین و بزرگ‌ترین انتقاد به مک‌لوهان، از «روش‌شناسی» می‌آید. منتقدان می‌گویند کار او «داده ندارد، روش ندارد، و فرضیه‌ای برای آزمون ندارد» و «شبه‌علمی» (pseudo-scientific) است — بیشتر «ضرب‌المثل» تا «نظریه».")
    D.bullet("توماس آتکینسون (Thomas Atkinson): «مک‌لوهان داده ندارد، روش ندارد، و فرضیه‌ای برای آزمون ندارد».")
    D.bullet("نیل پستمن (Neil Postman): نویسنده‌ی Amusing Ourselves to Death که از مک‌لوهان الهام گرفت، اما روش او را محکوم کرد: «مک‌لوهان پیش‌گو بود، نه تحلیلگر. او الگوها را می‌ساخت، نه آن‌ها را می‌سنجید.»")
    D.bullet("رابرت بولستر (Robert P. Bolster): مفهوم «گرم/سرد» «تعریف‌پذیر نیست» — نمی‌توان گفت یک رسانه «چقدر گرم» است. این تمایز، «دوگانه‌ی ساختگی» (pseudo-dichotomy) است.")

    D.h3("پاسخ مک‌لوهان: «روش‌شناسی متفاوت»، نه «اشتباه نبودن»")
    D.para("پاسخ مک‌لوهان، «روش‌شناسی متفاوت» بود، نه «اشتباه نبودن»: «مک‌لوهان از «تحلیل کمّی» دوری می‌کرد، چون معتقد بود رسانه «به‌شکل الگو» عمل می‌کند، نه به‌شکل عدد. او «تحلیل الگو» (pattern analysis) را به‌جای «آزمون فرضیه» به کار می‌برد. این، «گزینه‌ی روش‌شناختی» است، نه بی‌دقتی.» نکته‌ی کلیدی: باید «تمایز روش‌شناختی» را از «اشتباه» تفکیک کرد. مک‌لوهان «روشِ دیگری» داشت — و این روش، تا امروز، در «اکولوژی رسانه» زنده است.")

    D.h2("۱۱.۲. نقد تفسیری: پیش‌بینی، ابهام، و سوءتفسیر")
    D.para("مک‌لوهان، «پیش‌گو» نبود؛ اما آثارش به‌شکل «پیش‌بینی» خوانده می‌شوند. این «سوءتفسیر»، هم اعتبار او را بالا می‌برد و هم اعتبارش را پایین:")
    D.bullet("دونالد آرثر (Donald Arthur): ابهام «رسانه پیام است» — این جمله، به‌قدری باز است که هم «هر چیزی» و هم «هیچ چیزی» را توضیح می‌دهد.")
    D.bullet("جوزف بلنچ (Joseph Blanche): پیش‌بینی «دهکده‌ی جهانی» — آیا مک‌لوهان «پیش‌بینی» کرد، یا «توصیف» کرد؟ مرز بین این دو، مبهم است.")
    D.bullet("دالاس سمنر (Dallas Sommer): فناوری‌محوری — آیا مک‌لوهان «تکنولوژی‌محور» است، یا «فرهنگ‌محور»؟")

    D.h3("مک‌لوهان در اندیشه‌ی دیگران")
    D.para("جالب است که «مهم‌ترین» بازتاب‌ها از مک‌لوهان، از «منتقدان» و «بازنویسان» می‌آید:")
    D.bullet("جاشوا میروویتز (Joshua Meyrowitz): بازبینی و گسترش «دهکده‌ی جهانی» در «No Sense of Place» (1985) — نقش‌های اجتماعی و «حضور/غیاب».")
    D.bullet("مانوئل کاستلز (Manuel Castells): «شبکه در برابر دهکده» — «جامعه‌ی شبکه‌ای» (The Rise of the Network Society) بازخوانیِ «روستای جهانی» از منظر «ساختار شبکه».")
    D.bullet("ژان بودریار (Jean Baudrillard): «مک‌لوهانِ فرانسوی» — در «سیمولاکر و سیمولاسیون»، «پسامدرن» مک‌لوهان را در چارچوب «پساساختارگرایی» بازخوانی می‌کند.")

    D.h2("۱۱.۳. نقدهای معاصر: نژاد، پسااستعماری، و ژندر")
    D.para("در دهه‌های اخیر، «نقدهای معاصر» از منظر «نژاد و پسااستعماری» و «ژندر» بر مک‌لوهان وارد شده‌اند:")
    D.bullet("مایکل لِیتواک (Michael Litwack, 2021): «Extensions after Man» — نشان می‌دهد که مفهوم «گسترشِ بدن» (extensions of man) در Understanding Media، ریشه در «منطق نژادی» و «سیستم برده‌داری» دارد و «انسان» مک‌لوهان، «انسانِ سفید، مرد و اروپایی» است.")
    D.bullet("نقدهای فمینیستی (Sarah Sharma & Rianka Singh, 2022): «Re-Understanding Media» — بازخوانیِ فمینیستی‌ای از مک‌لوهان و نمایشِ «بی‌توجهی» او به «ژندر و بدنِ زنانه».")
    D.para("این نقدها، «لایه‌ی جدیدی» به مک‌لوهان‌شناسی اضافه کرده‌اند و نشان می‌دهند که «مفاهیمِ به‌نظرِ خنثی» (مثل «گسترش بدن» و «دهکده‌ی جهانی») در واقع «بارِ تاریخی-سیاسی» دارند.")

    D.h2("۱۱.۴. آیا مک‌لوهان «پیش‌گو» بود یا «توصیف‌گر»؟")
    D.para("این سؤال، «قله‌ی» نقدهاست. اگر مک‌لوهان «پیش‌گو» بود، اعتبارش «معجزه» است. اگر «توصیف‌گر» بود، اعتبارش «تحلیل» است. واقعیت، ترکیبی از هر دو است: مک‌لوهان «الگوها» را در «رسانه‌های الکترونیکی» (تلگراف، تلویزیون) «دید» و آن‌ها را «توصیف» کرد. اینترنت، این الگوها را «تأیید» کرد — اما مک‌لوهان «اینترنت» را «پیش‌بینی» نکرده بود؛ او «الگوی الکترونیکی» را توصیف کرده بود.")
    D.callout("جمع‌بندی فصل ۱۱:", "مک‌لوهان، «نظریه‌پرداز» به‌معنای «علمی-کمّی» نیست؛ «تحلیلگرِ الگو» است. نقدها، «روش‌شناسی» او را هدف گرفته‌اند، نه «دقتِ مشاهده‌اش». یک مک‌لوهان‌شناسِ حرفه‌ای، باید «هر دو» را بداند: «قدرت مشاهده» و «ضعف روش‌شناسی».")

    D.h2("۱۱.۵. تاریخچه‌ی نقدها: از ۱۹۶۰ تا امروز")
    D.table(
        headers=["دوره", "نوع نقد", "چهره‌های کلیدی", "موضوع"],
        rows=[
            ["۱۹۶۰–۱۹۷۰", "نقد روش‌شناسی", "آتکینسون، بولستر، پستمن", "مبهم، غیرعلمی، غیرقابل‌آزمون"],
            ["۱۹۷۰–۱۹۸۰", "نقد تفسیری", "آرثر، بلنچ، سمنر", "ابهام، پیش‌بینی، سوءتفسیر"],
            ["۱۹۸۰–۱۹۹۰", "بازخوانی فمینیستی/پسااستعماری", "فiske، Genosko، Jameson", "جنسیت، سرمایه‌داری، پسااستعماری"],
            ["۱۹۹۰–۲۰۰۰", "بازگشت دیجیتال", "Levinson، de Kerckhove، Logan", "مک‌لوهان و عصر دیجیتال"],
            ["۲۰۰۰–امروز", "نقد نژادی و پسااستعماری", "Litwack، Sharma، Singh", "نژاد، بدن، پسااستعماری"],
        ],
        col_widths=[3, 4, 5, 5],
    )
    D.para("این «تاریخچه‌ی نقدها» نشان می‌دهد که «مک‌لوهان‌شناسی»، یک «حوزه‌ی زنده» است: هر «دهه»، «لایه‌ی جدیدی» از نقد و بازخوانی به آثار او اضافه می‌کند. یک «مک‌لوهان‌شناسِ حرفه‌ای»، باید «همه‌ی این لایه‌ها» را بداند — نه فقط «آثار اصلی»، بلکه «ساختارِ نقد» آن‌ها را نیز.")

    D.h2("۱۱.۶. آیا «نقد» به معنای «رد» است؟")
    D.para("نکته‌ی مهم: «نقد» مک‌لوهان، به معنای «رد» او نیست. بیشتر نقدها، «روش‌شناسی» او را هدف گرفته‌اند، نه «دقتِ مشاهده‌اش». «قدرت مشاهده» مک‌لوهان — «دیدنِ الگوها» در «رسانه‌های الکترونیکی» — هنوز «بسیار قوی» است و «میراثش» در «اکولوژی رسانه» و «فلسفه‌ی فناوری» زنده است. «نقد»، «مک‌لوهان‌شناسی» را «غنی‌تر» کرده است، نه «بی‌ارزش‌تر». یک «مک‌لوهان‌شناسِ حرفه‌ای»، «هم» آثار اصلی و «هم» نقدها را می‌خواند — و از «هر دو» «فایده» می‌برد.")
    D.page_break()
